import json, collections, math
import task

SCORERS=['gpt2','qwen0.5b','tinyllama','qwen7b','llama2-7b']

def nll_variants(cands, ans):
    # per candidate: mean nll per scorer; answer-level: min over candidates, and exp-weighted sum
    per_cand = {}
    for i,c in enumerate(cands):
        a=ans[i]
        if a is None: continue
        f=c['features']
        d={}
        for s in SCORERS:
            tot,n=f.get(f'ar.{s}.nll_sum'),f.get(f'ar.{s}.n_tokens')
            if tot is not None and n: d[s]=tot/n
        per_cand.setdefault(a,[]).append(d)
    out={}
    for a,ds in per_cand.items():
        row={}
        for s in SCORERS:
            vals=[d[s] for d in ds if s in d]
            row['min_'+s]=min(vals) if vals else None
            row['minsum_'+s]=min(f.get(f'ar.{s}.nll_sum') for f in [c['features'] for c,aa in zip(cands,ans) if aa==a] if f.get(f'ar.{s}.nll_sum') is not None) if vals else None
            row['wsum_'+s]=sum(math.exp(-d[s]) for d in ds if s in d) if vals else None
        out[a]=row
    return out

for model in ['dream-base','llada-base']:
    items, gold = task.load_items('dev'), task.load_gold('dev')
    itms=[it for it in items if it['model']==model]
    print(f'== {model} ==')
    # tie cases
    tie_res=collections.Counter()
    flip_stats=collections.defaultdict(lambda:[0,0])  # variant -> [fixes, breaks]
    n_tie_majority_wrong=0; n_tie_majority_right=0
    for it in itms:
        g=gold[it['uid']]; cands=it['candidates']; ans=[c.get('answer') for c in cands]
        ok=[task.is_correct(a,g) for a in ans]
        if not any(ok): continue
        cnt=collections.Counter(a for a in ans if a is not None)
        best=max(cnt.values()); winners=[a for a,c in cnt.items() if c==best]
        if len(winners)<2: continue
        maj_ans=winners[0]; maj_ok=task.is_correct(maj_ans,g)
        correct_ans=next(a for a,o in zip(ans,ok) if o)
        if maj_ok:
            n_tie_majority_right+=1
            for v in [f'min_{s}' for s in SCORERS]+[f'wsum_{s}' for s in SCORERS]:
                # if variant flips away from correct, that's a break
                row=nll_variants(cands,ans)
                vals={a:row[a][v] for a in winners if row[a][v] is not None}
                b=min(vals,key=vals.get); 
                if not task.is_correct(b,g): flip_stats[v+'_tie_any'][1]+=1
        else:
            n_tie_majority_wrong+=1
            row=nll_variants(cands,ans)
            for v in [f'min_{s}' for s in SCORERS]+[f'wsum_{s}' for s in SCORERS]:
                vals={a:row[a][v] for a in winners if row[a][v] is not None}
                if len(vals)<2: continue
                b=min(vals,key=vals.get)
                if task.is_correct(b,g): flip_stats[v+'_tie_fix'][0]+=1
                else: flip_stats[v+'_tie_fix'][1]+=1
    print(f'  ties: {n_tie_majority_right+n_tie_majority_wrong} (majority-earliest right {n_tie_majority_right})')
    for s in ['qwen7b','llama2-7b','gpt2']:
        for kind in ['min_','wsum_']:
            k=kind+s+'_tie_fix'
            if k in flip_stats: print(f'    {k}: fix {flip_stats[k][0]} / keep-wrong {flip_stats[k][1]}')
"
